// Spotify service constants and HTML templates

// Base64 encoded astronaut mascot image - replace this value with your encoded string
const String encodedImg = '';

// Spotify authentication success callback HTML template
String getSpotifyCallbackHtml() {
  return '''<!DOCTYPE html>
<html>
<head>
  <title>Interestnaut - Authentication Successful</title>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700&display=swap');
    
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }
    
    body {
      background: linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%);
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: #e0e0e0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    
    .container {
      text-align: center;
      max-width: 600px;
      padding: 80px 50px;
      background: rgba(20, 20, 20, 0.8);
      border-radius: 16px;
      border: 1px solid rgba(147, 51, 234, 0.2);
      backdrop-filter: blur(10px);
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
    }
    
    .logo {
      width: 80px;
      height: 80px;
      margin: 0 auto 24px;
      background: url('data:image/png;base64,$encodedImg') center/contain no-repeat;
      border-radius: 50%;
      box-shadow: 0 10px 30px rgba(147, 51, 234, 0.3);
    }
    
    .brand {
      font-size: 20px;
      font-weight: 100;
      background: linear-gradient(135deg, #9333ea, #c084fc);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      text-transform: uppercase;
      letter-spacing: 2.4px;
      margin-bottom: 24px;
      transform: scaleX(1.15);
      line-height: 1.0;
    }
    
    .success-icon {
      width: 64px;
      height: 64px;
      margin: 0 auto 24px;
      background: linear-gradient(135deg, #22c55e, #16a34a);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
      color: white;
      box-shadow: 0 10px 30px rgba(34, 197, 94, 0.3);
      animation: pulse 2s infinite;
    }
    
    @keyframes pulse {
      0%, 100% { transform: scale(1); }
      50% { transform: scale(1.05); }
    }
    
    h1 {
      font-size: 20px;
      font-weight: 200;
      color: #ffffff;
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 2.5px;
      transform: scaleX(1.25);
      line-height: 1.0;
    }
    
    .subtitle {
      font-size: 15px;
      color: #b3b3b3;
      margin-bottom: 32px;
      font-weight: 200;
      letter-spacing: 0.8px;
      line-height: 1.8;
      transform: scaleY(1.1);
    }
    
    .spotify-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(29, 185, 84, 0.1);
      border: 1px solid rgba(29, 185, 84, 0.3);
      border-radius: 24px;
      padding: 8px 16px;
      font-size: 14px;
      color: #1ed760;
      font-weight: 500;
    }
    
    .close-hint {
      font-size: 14px;
      color: #64748b;
      margin-top: 24px;
      font-weight: 300;
    }
    
    .particles {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      pointer-events: none;
      z-index: -1;
    }
    
    .particle {
      position: absolute;
      width: 2px;
      height: 2px;
      background: rgba(147, 51, 234, 0.4);
      border-radius: 50%;
      animation: float 6s infinite linear;
    }
    
    @keyframes float {
      0% { transform: translateY(100vh) rotate(0deg); opacity: 0; }
      10% { opacity: 1; }
      90% { opacity: 1; }
      100% { transform: translateY(-10vh) rotate(360deg); opacity: 0; }
    }
  </style>
</head>
<body>
  <div class="particles">
    <div class="particle" style="left: 10%; animation-delay: -1s;"></div>
    <div class="particle" style="left: 20%; animation-delay: -2s;"></div>
    <div class="particle" style="left: 30%; animation-delay: -3s;"></div>
    <div class="particle" style="left: 40%; animation-delay: -4s;"></div>
    <div class="particle" style="left: 50%; animation-delay: -5s;"></div>
    <div class="particle" style="left: 60%; animation-delay: -6s;"></div>
    <div class="particle" style="left: 70%; animation-delay: -1.5s;"></div>
    <div class="particle" style="left: 80%; animation-delay: -2.5s;"></div>
    <div class="particle" style="left: 90%; animation-delay: -3.5s;"></div>
  </div>
  <div class="container">
    <div class="brand">Interestnaut</div>
    <div class="logo"></div>
    <h1>Authentication Successful</h1>
    <p class="subtitle">Your Spotify account has been connected successfully</p>
    <div class="spotify-badge">
      <span style="color: #1ed760;">●</span>
      Connected to Spotify
    </div>
    <p class="close-hint">You can close this window and return to the app</p>
  </div>
</body>
</html>''';
}